    public static function entityDefinitions(): array
    {
        return array_map(static fn (array $record): array => [$record['source'], $record['model'], $record['domain']], self::recordDefinitions());
    }

    public static function domainGates(): array
    {
        $gates = [];
        foreach (self::recordDefinitions() as $record) {
            $gates[$record['domain']] = [$record['module'], $record['domain'] === 'operations_assets' ? ['warehouse.view', 'machinery-operations.view'] : [$record['permissions'][0]]];
        }
        $gates['operations_safety_medical'] = ['safety-management', ['safety-management.view']];
        return $gates;
    }

    public static function domainModuleAlternatives(): array
    {
        return ['operations_assets' => ['basic-warehouse', 'machinery-operations']];
    }

    public static function entityPermissions(): array
    {
        return array_map(static fn (array $record): array => $record['permissions'], self::recordDefinitions());
    }

    public static function sourcePermissions(): array
    {
        return ['operations_warehouse' => ['warehouse.view'], 'operations_assets' => [],
            'operations_machinery' => ['machinery-operations.view'], 'operations_quality' => ['quality-control.view'],
            'operations_safety' => ['safety-management.view'], 'operations_safety_medical' => ['safety-management.view'],
            'operations_schedule' => ['schedule.view'], 'operations_site_requests' => ['site_requests.view']];
    }

    public static function parentColumns(): array
    {
        return array_map(static function (array $record): array {
            $parents = $record['parents'];
            if ($record['domain'] === 'operations_safety_medical') { unset($parents['employee_id']); }
            return $parents;
        }, self::recordDefinitions());
    }

    public static function organizationColumns(): array
    {
        return array_map(static fn (array $record): ?string => $record['organization_column'], self::recordDefinitions());
    }

    public static function organizationAggregates(): array
    {
        $aggregates = [];
        foreach (self::recordDefinitions() as $type => $record) {
            if (str_contains($type, 'snapshot') && ! str_contains($type, 'demand_snapshot')) {
                $aggregates[$type] = $record['project_column'] ?? true;
            }
        }
        $aggregates['safety_admission_snapshot'] = true;
        return $aggregates;
    }

    public static function retrievalCoverageDefinitions(): array
    {
        return array_map(static fn (array $record): array => ['indexed' => true, 'mode' => 'indexed_private',
            'reason' => 'Every row has an explicit scalar whitelist and current organization, project, parent and subject checks; monetary fields remain live only.'], self::recordDefinitions());
    }

    public static function safeSelectColumns(): array
    {
        return array_map(static fn (array $record): array => array_values(array_unique([...$record['read_fields'], ...$record['version_columns'], ...array_keys($record['parents'])])), self::recordDefinitions());
    }

    public static function navigationTemplates(): array
    {
        return array_map(static fn (array $record): string => $record['navigation'], self::recordDefinitions());
    }

    public static function observerDefinitions(): array
    {
        $models = [];
        foreach (self::recordDefinitions() as $type => $record) { $models[$record['model']] = [$record['source'], $type]; }
        return $models;
    }

