    public static function monetaryFields(): array
    {
        return ['consumption_value_minor', 'cost_turnover', 'on_hand_value_minor', 'operating_cost_per_hour', 'total_value', 'unit_price', 'unit_price_minor'];
    }

    public static function numericFields(): array
    {
        $fields = [];
        foreach (self::recordDefinitions() as $record) {
            foreach ($record['column_types'] as $field => $type) {
                if (in_array($field, $record['read_fields'], true) && in_array($type, ['decimal', 'integer', 'unsignedInteger', 'smallInteger', 'unsignedSmallInteger', 'bigInteger', 'unsignedBigInteger'], true)
                    && ! str_ends_with($field, '_id') && $field !== 'id') { $fields[] = $field; }
            }
        }
        return array_values(array_unique($fields));
    }

    public static function structuredFields(): array
    {
        return array_values(array_unique(array_merge(...array_column(self::recordDefinitions(), 'read_fields'))));
    }

    public static function factFieldGroups(): array
    {
        $groups = ['money' => self::monetaryFields(), 'quantity' => array_values(array_diff(self::numericFields(), self::monetaryFields())), 'date' => [], 'status' => [], 'owner' => []];
        foreach (self::structuredFields() as $field) {
            if (str_ends_with($field, '_at') || str_ends_with($field, '_date') || in_array($field, ['valid_from', 'valid_to', 'valid_until', 'effective_from', 'effective_to', 'effective_until', 'as_of', 'planned_start', 'planned_end', 'active_from', 'active_until'], true)) { $groups['date'][] = $field; }
            if (str_contains($field, 'status') || in_array($field, ['result', 'is_active', 'ready', 'blocked', 'verified', 'complete', 'reconciliation_status', 'quality_status'], true)) { $groups['status'][] = $field; }
            if (in_array($field, ['employee_id', 'assigned_user_id', 'actor_user_id', 'owner_user_id', 'responsible_user_id', 'requested_by_user_id', 'inspected_by_user_id', 'reported_by_user_id', 'user_id'], true)) { $groups['owner'][] = $field; }
        }
        return $groups;
    }

    public static function domainDefinitions(): array
    {
        $definitions = [];
        foreach (self::domainGates() as $domain => [$module]) {
            $records = array_filter(self::recordDefinitions(), static fn (array $record): bool => $record['domain'] === $domain);
            $types = array_keys($records);
            $primary = $types[0];
            $fields = array_values(array_unique(array_merge(...array_column($records, 'read_fields'))));
            $entity = ['type' => 'string', 'enum' => $types];
            $fieldList = ['type' => ['array', 'null'], 'items' => ['type' => 'string', 'enum' => $fields]];
            $schema = static fn (array $properties): array => ['type' => 'object', 'properties' => $properties, 'required' => array_keys($properties), 'additionalProperties' => false];
            $id = ['anyOf' => [['type' => 'integer', 'minimum' => 1], ['type' => 'string', 'minLength' => 1, 'maxLength' => 64, 'pattern' => '^[A-Za-z0-9-]+$']]];
            $schemas = ['search' => $schema(['entity_type' => $entity, 'query' => ['type' => 'string', 'maxLength' => 200], 'project_id' => ['type' => ['integer', 'null'], 'minimum' => 1], 'limit' => ['type' => 'integer', 'minimum' => 1, 'maximum' => 20], 'fields' => $fieldList]),
                'read' => $schema(['entity_type' => $entity, 'id' => $id, 'fields' => $fieldList]), 'navigation' => $schema(['entity_type' => $entity, 'id' => $id])];
            $fieldPermissions = [];
            foreach (array_intersect($fields, self::monetaryFields()) as $field) { $fieldPermissions[$field] = ['finance.view']; }
            $permissions = $domain === 'operations_assets' ? [] : [$records[$primary]['permissions'][0]];
            $definitions[] = new AssistantDomainDefinition($domain, $module, $primary, $permissions, $fields, $schemas, array_keys($schemas), $records[$primary]['navigation'], $records[$primary]['source'], $types, $fieldPermissions,
                array_map(static fn (array $record): array => $record['permissions'], $records));
        }
        return $definitions;
    }

