    public static function identifierTargets(): array
    {
        return ['warehouse' => 'warehouse', 'zone' => 'warehouse_zone', 'cell' => 'warehouse_storage_cell', 'asset' => 'material',
            'inventory_act' => 'inventory_act', 'movement' => 'warehouse_movement', 'logistic_unit' => 'warehouse_logistic_unit'];
    }

    public static function applyActorScope(string $type, Builder $query, User $actor, int $organizationId, AuthorizationService $authorization, AssistantDataAccessPolicy $policy): void
    {
        $record = self::recordDefinitions()[$type] ?? null;
        if ($record === null) { return; }
        $table = $query->getModel()->getTable();
        if ($record['domain'] === 'operations_assets') {
            $modules = app(OrganizationEntitlementService::class)->getEffectiveModules($organizationId)->pluck('slug')->all();
            $warehouse = in_array('basic-warehouse', $modules, true) && $authorization->canCurrent($actor, 'warehouse.view', ['organization_id' => $organizationId]);
            $machinery = in_array('machinery-operations', $modules, true) && $authorization->canCurrent($actor, 'machinery-operations.view', ['organization_id' => $organizationId]);
            if (! $warehouse && ! $machinery) { $query->whereRaw('1 = 0'); }
        }
        if ($type === 'warehouse_identifier') {
            $targets = [];
            foreach (self::identifierTargets() as $kind => $parentType) {
                $parent = $policy->entityQuery($actor, $organizationId, $parentType);
                if ($parent === null) { continue; }
                if (in_array($kind, ['zone', 'cell', 'logistic_unit'], true)) {
                    $parent->where(static fn (Builder $match) => $match->whereNull($table.'.warehouse_id')
                        ->orWhereColumn($parent->getModel()->getTable().'.warehouse_id', $table.'.warehouse_id'));
                }
                $targets[$kind] = $parent->select($parent->getModel()->getQualifiedKeyName());
            }
            $query->where(static function (Builder $scope) use ($table, $targets): void {
                $scope->whereRaw('1 = 0');
                foreach ($targets as $kind => $parent) {
                    $scope->orWhere(static fn (Builder $branch) => $branch->where($table.'.entity_type', $kind)->whereIn($table.'.entity_id', $parent));
                }
            });
        }
        if ($type === 'site_request_group') { $query->visibleToActor((int) $actor->id); }
        if (array_key_exists('employee_id', $record['column_types'])) {
            $employee = $record['domain'] === 'operations_safety_medical'
                ? \App\BusinessModules\Features\WorkforceManagement\Domain\HR\Models\WorkforceEmployee::query()->where('workforce_employees.organization_id', $organizationId)
                : $policy->entityQuery($actor, $organizationId, 'workforce_employee');
            if ($employee === null) { $query->whereRaw('1 = 0'); return; }
            $employeeTable = $employee->getModel()->getTable();
            $accessibleProjects = app(UserProjectAccessService::class)->queryAccessibleProjects($actor, $organizationId)->select('projects.id');
            $employee->whereNotExists(static function ($assignments) use ($organizationId, $employeeTable, $accessibleProjects): void {
                $assignments->selectRaw('1')->from('workforce_employee_assignments as operations_subject_assignment')
                    ->whereColumn('operations_subject_assignment.employee_id', $employeeTable.'.id')
                    ->where('operations_subject_assignment.organization_id', $organizationId)
                    ->whereNull('operations_subject_assignment.deleted_at')
                    ->where('operations_subject_assignment.status', 'active')
                    ->whereDate('operations_subject_assignment.valid_from', '<=', now()->toDateString())
                    ->where(static fn ($period) => $period->whereNull('operations_subject_assignment.valid_to')->orWhereDate('operations_subject_assignment.valid_to', '>=', now()->toDateString()))
                    ->whereNotNull('operations_subject_assignment.project_id')->whereNotIn('operations_subject_assignment.project_id', $accessibleProjects);
            });
            $nullable = $record['parents']['employee_id']['nullable'] ?? false;
            $query->where(static function (Builder $subjects) use ($employee, $employeeTable, $table, $nullable): void {
                if ($nullable) { $subjects->whereNull($table.'.employee_id')->orWhereIn($table.'.employee_id', $employee->select($employeeTable.'.id')); }
                else { $subjects->whereIn($table.'.employee_id', $employee->select($employeeTable.'.id')); }
            });
        }
        if (in_array($type, ['safety_incident_row', 'safety_transition_event'], true)) {
            $parents = [];
            foreach (['incident' => 'safety_incident', 'violation' => 'safety_violation', 'corrective_action' => 'safety_corrective_action'] as $subject => $parentType) {
                $parent = $policy->entityQuery($actor, $organizationId, $parentType);
                if ($parent !== null) { $parents[$subject] = $parent->select($parent->getModel()->getTable().'.id'); }
            }
            $query->where(static function (Builder $scope) use ($table, $parents): void {
                $scope->whereRaw('1 = 0');
                foreach ($parents as $subject => $parent) {
                    $scope->orWhere(static fn (Builder $branch) => $branch->where($table.'.subject_type', $subject)->whereIn($table.'.subject_id', $parent));
                }
            });
        }
    }
}
